def aligned_tree(net, root=None, kappa=L1.KAPPA, mode="ring"):
    """沿 BFS 生成树做**平行移动积分**，得到全局坐标（确定性、`O(E)`、无迭代）。

    规则（纯 id + 环序）：BFS 从 root 出发；处理边 i→w 时
      g = M_i · dir_i(w)                              （i 的全局标架下的 i→w 方向）
      p_w = p_i + (r_i + r_w)·g                       （树边精确满足相切目标长）
      M_w = R(u→−g)，其中 u = dir_w(i)                （把 w 标架的「指向 i」转到 −g）

    返回 {"pos", "frames", "tree_edges", "holonomy"}：
      holonomy[(i,w)] = 用 i 的标架预测 w 的位置与树位置之差（非树边）。
      该量**非零是几何事实**（离散曲率无法在平面容纳），不是误差 —— 见模块 docstring。
    """
    ids = net.ids()
    if not ids:
        return {"pos": {}, "frames": {}, "tree_edges": set(), "holonomy": {}}
    r = _radius(net, kappa)
    fr = _frames(net, kappa, mode)
    root = ids[0] if root is None else root
    pos = {root: (0.0, 0.0, 0.0)}
    M = {root: I3}
    tree_edges = set()
    q = deque([root])
    while q:
        i = q.popleft()
        for (w, dl) in fr[i].items():
            if w in pos:
                continue
            g = mat_apply(M[i], dl)
            pos[w] = tuple(pos[i][k] + (r[i] + r[w]) * g[k] for k in range(3))
            M[w] = rot_from_uv(fr[w][i], tuple(-x for x in g))
            tree_edges.add((i, w) if i < w else (w, i))
            q.append(w)
    hol = {}
    for (i, w) in L1.edge_list(net):
        if (i, w) in tree_edges:
            continue
        g = mat_apply(M[i], fr[i][w])
        pred = tuple(pos[i][k] + (r[i] + r[w]) * g[k] for k in range(3))
        hol[(i, w)] = math.dist(pos[w], pred)
    return {"pos": pos, "frames": M, "tree_edges": tree_edges, "holonomy": hol}

def sigma_global(net):
    """GT-008 全局 σ = |V| / |E| = 2 / ⟨deg⟩。"""
    E = net.E()
    return (net.V() / E) if E else float("inf")

def edge_set(net):
    """无向边集合（id 对，规范化 (min,max)）。"""
    return {(v, w) if v < w else (w, v)
            for v in net.ids() for w in net.rot[v]}

def _edge_set(net):
    """无向边集合（规范化 (min,max)，确定性排序）。"""
    return sorted({(v, w) if v < w else (w, v)
                   for v in net.ids() for w in net.rot[v]})

def _cpu_commit_expect(core):
    """CPU 版的「通过 §3.5 交集」候选有序角点表（按 key 升序 = 提交顺序）。"""
    cands = core.propose()
    accept = core.resolve(cands)
    out = []
    for c in sorted((c for c in cands if c["type"] == CREATION),
                    key=lambda c: c["key"]):
        if all(id(c) in accept.get(v, ()) for v in set(c["corners"])):
            out.append(tuple(c["corners"]))
    return out

def seed_at_V(V, base="icosa"):
    """构造 V ≥ 12 的三角剖分起点：由 icosa 逐次锥化首个真面，每次 +1 元胞。"""
    net = RotNet(SEEDS[base]())
    while net.V() < V:
        for cyc in net.faces():
            vs = net.face_vertices(cyc)
            if (len(vs) == 3 and len(set(vs)) == 3
                    and net.cone_tri_face(*vs) is not None):
                break
        else:
            break
    return net

def intersection(inc_c_row, acc, cand_len, n_cand):
    """§3.5 交集提交判据：候选存活 ⟺ 它的每个角点都接受它。

    按候选汇总被接受的入射数，与角点数相等即存活。
    """
    if int(cand_len.size) == 0:
        return cp.zeros(0, dtype=bool)
    cnt = cp.bincount(inc_c_row.astype(cp.int64),
                      weights=acc.astype(cp.float64),
                      minlength=int(n_cand)).astype(cp.int64)
    return cnt == cand_len.astype(cp.int64)

def degree_next(deg, corner_nodes, break_u=None, break_v=None, dmin=3):
    """§4.3 修剪标记：先算下一帧度数，再标出 deg < dmin 的位置。

    deg_{t+1}(v) = deg_t(v) + (以 v 为角点的锥化次数) − (v 的入射断边数)。
    corner_nodes / break_u / break_v 均为**位置下标**。
    """
    nv = int(deg.size)
    dn = deg.astype(cp.int64)
    if int(corner_nodes.size):
        dn = dn + cp.bincount(corner_nodes.astype(cp.int64),
                              minlength=nv).astype(cp.int64)
    for arr in (break_u, break_v):
        if arr is not None and int(arr.size):
            dn = dn - cp.bincount(arr.astype(cp.int64), minlength=nv).astype(cp.int64)
    return dn, cp.where(dn < int(dmin))[0].astype(cp.int32)
